### Example Code Snippets

#### Character Creation Component (Preact)
```tsx
// src/client/components/CharacterCreation.tsx
import { useState } from 'preact/hooks';
import { createCharacter } from '../../services/api';

interface Character {
  name: string;
  gender: string;
  age: number;
  appearance: string;
  traits: string;
  background: string;
}

const CharacterCreation: preact.FunctionComponent = () => {
  const [character, setCharacter] = useState<Character>({
    name: '',
    gender: '',
    age: 0,
    appearance: '',
    traits: '',
    background: '',
  });

  const handleSubmit = async (e: Event) => {
    e.preventDefault();
    await createCharacter(character);
    setCharacter({ name: '', gender: '', age: 0, appearance: '', traits: '', background: '' });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input type="text" placeholder="Name" value={character.name} onChange={(e) => setCharacter({ ...character, name: e.target.value })} />
      <input type="text" placeholder="Gender" value={character.gender} onChange={(e) => setCharacter({ ...character, gender: e.target.value })} />
      <input type="number" placeholder="Age" value={character.age} onChange={(e) => setCharacter({ ...character, age: parseInt(e.target.value) })} />
      <input type="text" placeholder="Appearance" value={character.appearance} onChange={(e) => setCharacter({ ...character, appearance: e.target.value })} />
      <input type="text" placeholder="Traits" value={character.traits} onChange={(e) => setCharacter({ ...character, traits: e.target.value })} />
      <textarea placeholder="Background" value={character.background} onChange={(e) => setCharacter({ ...character, background: e.target.value })} />
      <button type="submit">Create Character</button>
    </form>
  );
};

export default CharacterCreation;
```

#### Character Creation API (Express)
```ts
// src/server/routes/characters.ts
import express from 'express';
import { createCharacter } from '../../utils/cohere-ai';

const router = express.Router();

router.post('/', async (req, res) => {
  const { name, gender, age, appearance, traits, background } = req.body;
  const character = { name, gender, age, appearance, traits, background };

  try {
    const createdCharacter = await createCharacter(character);
    res.status(201).json(createdCharacter);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create character' });
  }
});

export default router;
```

#### Character Model (TypeScript)
```ts
// src/models/character.ts
export interface Character {
  name: string;
  gender: string;
  age: number;
  appearance: string;
  traits: string;
  background: string;
}
```

